import{_ as n,C as i,c as s,o as d,ag as o,j as r,G as t,a as l}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"Managing Referrals","description":"","frontmatter":{},"headers":[],"relativePath":"guide/admin-portal/managing-referrals.md","filePath":"guide/admin-portal/managing-referrals.md","lastUpdated":1752132375000}'),f={name:"guide/admin-portal/managing-referrals.md"};function h(g,e,u,c,p,m){const a=i("ZoomableImage");return d(),s("div",null,[e[0]||(e[0]=o('<h1 id="managing-referrals" tabindex="-1">Managing Referrals <a class="header-anchor" href="#managing-referrals" aria-label="Permalink to &quot;Managing Referrals&quot;">​</a></h1><p>FluentAffiliate gives you a clear and powerful dashboard to manage and track every affiliate referral. This is where you can see all successful conversions, review their status, and take action when needed.</p><p>In this guide, we&#39;ll walk you through the features of the Referrals page to help you stay in control.</p><h2 id="referral-dashboard-overview" tabindex="-1">Referral Dashboard Overview <a class="header-anchor" href="#referral-dashboard-overview" aria-label="Permalink to &quot;Referral Dashboard Overview&quot;">​</a></h2><p>To get started, click on the <strong>Referrals</strong> tab from the main FluentAffiliate menu. This will take you to the main referrals dashboard.</p><h3 id="adding-a-new-referral" tabindex="-1">Adding a New Referral <a class="header-anchor" href="#adding-a-new-referral" aria-label="Permalink to &quot;Adding a New Referral&quot;">​</a></h3><p>At the top right, you&#39;ll see the <strong>+ New Referral</strong> button. This allows you to manually create a referral and assign it to an affiliate, which can be useful for offline sales or special cases.</p><h3 id="filtering-referrals-by-status" tabindex="-1">Filtering Referrals by Status <a class="header-anchor" href="#filtering-referrals-by-status" aria-label="Permalink to &quot;Filtering Referrals by Status&quot;">​</a></h3><p>Just below the page title, you can use the filter tabs to quickly view referrals based on their status:</p><ul><li><strong>All:</strong> Shows every referral that has ever been recorded.</li><li><strong>Unpaid:</strong> Shows approved referrals that are waiting to be included in a payout.</li><li><strong>Paid:</strong> Shows referrals for which commissions have already been paid to the affiliate.</li><li><strong>Pending:</strong> Shows new referrals that are awaiting your approval before they can be paid.</li><li><strong>Rejected:</strong> Shows any referrals that you have marked as rejected, meaning no commission will be paid for them.</li></ul><h3 id="referrals-details-table" tabindex="-1">Referrals Details Table <a class="header-anchor" href="#referrals-details-table" aria-label="Permalink to &quot;Referrals Details Table&quot;">​</a></h3><p>The main table lists every referral with all the important details, giving you a transparent overview.</p><ul><li><strong>ID:</strong> A unique identification number for each referral.</li><li><strong>Affiliate:</strong> The name of the affiliate who generated the referral. You can click on their name to view their full profile.</li><li><strong>Amount:</strong> The commission amount earned from that specific referral.</li><li><strong>Description:</strong> Details about the product or service that was purchased.</li><li><strong>Reference:</strong> A source or order ID linked to the referral.</li><li><strong>Status:</strong> The current status of the referral <strong>Paid</strong>, <strong>Pending</strong>, <strong>Unpaid</strong>, or <strong>Rejected</strong>.</li><li><strong>Type:</strong> The source of the commission, such as a product sale or a form submission.</li><li><strong>Date:</strong> The exact date the referral was created.</li></ul>',13)),r("p",null,[t(a,{src:"/guide/public/images/admin-portal/managing-referrals/referrals-list-overview.webp",alt:"Referral Dashboard Overview"})]),e[1]||(e[1]=o('<h3 id="managing-individual-referrals" tabindex="-1">Managing Individual Referrals <a class="header-anchor" href="#managing-individual-referrals" aria-label="Permalink to &quot;Managing Individual Referrals&quot;">​</a></h3><p>At the end of each referral&#39;s row is a three-dot menu that contains key actions:</p><ul><li><strong>Edit:</strong> Allows you to modify the details of the referral, such as its status or amount.</li><li><strong>Delete:</strong> Permanently removes the referral record.</li></ul><h3 id="search-and-sort-tools" tabindex="-1">Search and Sort Tools <a class="header-anchor" href="#search-and-sort-tools" aria-label="Permalink to &quot;Search and Sort Tools&quot;">​</a></h3><ul><li><p><strong>Search bar</strong>: Quickly find specific referrals by entering keywords or details.</p></li><li><p><strong>Column Selection</strong>: Choose which columns you want to display in the referral table.</p></li><li><p><strong>Sort</strong>: Sort your referrals by Amount, ID, or Reference in ascending or descending order. Don&#39;t forget to hit <strong>Apply</strong> after sorting.</p></li></ul>',5)),r("p",null,[t(a,{src:"/guide/public/images/admin-portal/managing-referrals/search-and-sort-tools.webp",alt:"Affiliate Search and Sort Tools"})]),e[2]||(e[2]=r("h3",{id:"add-a-new-referral",tabindex:"-1"},[l("Add a New Referral "),r("a",{class:"header-anchor",href:"#add-a-new-referral","aria-label":'Permalink to "Add a New Referral"'},"​")],-1)),e[3]||(e[3]=r("p",null,"Want to manually add an referral to your site?",-1)),e[4]||(e[4]=r("p",null,[l("First, click the "),r("strong",null,"New Referral"),l(" button.")],-1)),r("p",null,[t(a,{src:"/guide/public/images/admin-portal/managing-referrals/add-new-referral-button.webp",alt:"Add New Referral Button"})]),e[5]||(e[5]=o("<p>After clicking the button, a form will slide in from the right side of your screen. Here, you&#39;ll need to fill in the details for the new referral.</p><ul><li><strong>Select Affiliate:</strong> Start typing the name of the affiliate you want to credit and select them from the list. This is the most important field.</li><li><strong>Type:</strong> Choose the type of referral from the dropdown menu (e.g., Sale, Opt-in).</li><li><strong>Amount:</strong> Enter the exact commission amount the affiliate will earn for this referral.</li><li><strong>Status:</strong> Set the initial status of the referral. You can choose from Unpaid, Paid, Pending, or Rejected.</li><li><strong>Description:</strong> Add a short note or description for your own records, explaining why this referral was added manually (e.g., &quot;Manual entry for phone order #5512&quot;).</li><li><strong>Source (Optional):</strong> You can enter a source slug here to provide extra context about where the referral came from (e.g., manual_sale).</li><li><strong>Provider ID (Optional):</strong> If this referral corresponds to an order in another system (like WooCommerce), you can enter the Order ID here to link them for easy reference.</li></ul><p>Once you have filled in all the necessary details, click the <strong>Create Manual Referral</strong> button at the bottom of the form.</p><p>The new referral will be instantly created and will appear in your main referrals list, assigned to the affiliate you selected.</p>",4)),r("p",null,[t(a,{src:"/guide/public/images/admin-portal/managing-referrals/create-manual-referral.webp",alt:"Create Manual Referral"})]),e[6]||(e[6]=r("p",null,"That's it! Your new referral will now appear in the list.",-1))])}const y=n(f,[["render",h]]);export{b as __pageData,y as default};
